import subprocess
res={}
for i in range(1,256):
    b=bytes([i])
    try:
        out=subprocess.run(["/workspace/executable","dump","bash"],env={"V":b.decode('latin1')},capture_output=True).stdout
    except Exception as e:
        print(i,e); continue
    # env encoding: python encodes str via fsencode (utf-8 surrogateescape) -> latin1 char becomes utf-8 2 bytes for >127
    res[i]=out
for i in range(1,128):
    print(i, repr(chr(i)), res[i])
PYEOF

