import subprocess, os, shlex, sys, json

DIRENV = os.environ.get("DIRENV_BIN", "/workspace/executable")

class Session:
    def __init__(self, home="/tmp/sb/home", cwd="/tmp/sb/proj", extra=None):
        self.env = {"HOME": home, "PATH": "/usr/bin:/bin", "TERM": "dumb"}
        if extra: self.env.update(extra)
        self.cwd = cwd
    def run(self, *args, cwd=None, stdin=None):
        p = subprocess.run([DIRENV]+list(args), env=self.env, cwd=cwd or self.cwd,
                           capture_output=True, input=stdin)
        return p
    def export(self, shell="bash", quiet=False):
        p = self.run("export", shell)
        if not quiet:
            sys.stdout.write("STDERR: "+p.stderr.decode(errors="replace")+"\n")
            sys.stdout.write("STDOUT: "+p.stdout.decode(errors="replace")+"\n")
            sys.stdout.write("EXIT: %d\n" % p.returncode)
        # apply to env via bash
        if shell=="bash" and p.stdout:
            out = subprocess.run(["/usr/bin/bash","-c", p.stdout.decode()+"\nexport -p"],
                                 env=self.env, cwd=self.cwd, capture_output=True)
            # simpler: use env after eval
            out = subprocess.run(["/usr/bin/bash","-c", p.stdout.decode()+'\nenv -0'],
                                 env=self.env, cwd=self.cwd, capture_output=True)
            newenv={}
            for item in out.stdout.split(b"\0"):
                if not item: continue
                k,_,v=item.partition(b"=")
                newenv[k.decode()]=v.decode(errors="replace")
            for k in ("PWD","SHLVL","_","OLDPWD"):
                newenv.pop(k,None)
            self.env=newenv
        return p
    def cd(self, d):
        self.cwd = d
PYEOF
echo ok

